SCRIPT.update({E5M: "src/ext_E5_ablation_lc.py (src/extlib.py)", E5D: "src/ext_E5_ablation_lc.py (src/extlib.py)", E5L: "src/ext_E5_ablation_lc.py", E5I: "src/ext_E5_ablation_lc.py"})
KP = sorted(df(E5L)[df(E5L)['sample'] == 'pooled'].n_train_women.unique()); K1, K2, K3 = float(KP[0]), float(KP[1]), float(KP[2]); kc = lambda k: calc('learning-curve k', int(k), '{:.0f}', E5L, 'unique n_train_women')
e = []; a = e.append; GN = {"phase": "phase", "hormones": "hormones (E2, P)", "PSST": "PSST", "BDI": "BDI", "BAI": "BAI"}
a("### 8.5 E5: Ablation study and learning curves\n")
a("Math note: `docs/math/E5_ablation_and_learning_curves.md`. **Ablation:** start from the full set D (phase, hormones, PSST, BDI, BAI), drop one feature group at a time, refit the whole nested-CV pipeline and compare. Change in RMSE = without group minus full set (positive = the group helped; negative = the model was better without it), with 95% CIs from resampling the same women. 'Alone' = the group by itself. Ridge in all three samples; random forest for the drop-one sets in the pooled and longitudinal samples. **Learning curve:** leave-one-woman-out where the model may only use k randomly chosen other women.\n")
for s_ in ["pooled", "long", "cross2long"]:
    a(f"**Ablation, ridge, {SMP[s_]} sample** " + (f"(training {nn('cross')}; test {nn('long')})" if s_ == "cross2long" else f"({nn(s_)})") + ". R2 versus the mean baseline [95% CI]:\n")
    a("| Target | Group | R2 without the group | Change in RMSE when dropped [CI] | R2 of the group alone |\n|---|---|---|---|---|")
    for t in TS:
        a(f"| {TN[t]} | (full set D) | {ci('results/phase4_metrics.csv', dict(sample=s_, target=t, model='ridge', fset='D'), 'R2_oos', '{:+.3f}', label=f'E5 full D {s_} {t}')} | - | - |")
        for g_, lab in GN.items():
            a(f"| | {lab} | {ci(E5M, dict(sample=s_, target=t, model='ridge', fset='D-' + g_), 'R2_oos', '{:+.3f}', label=f'E5 drop {g_} {s_} {t}')} | {ci(E5D, dict(sample=s_, target=t, first='ridge/D-' + g_, second='ridge/D', metric='RMSE'), 'delta', '{:+.3f}', lo='lo', hi='hi', label=f'E5 dRMSE drop {g_} {s_} {t}')} | {ci(E5M, dict(sample=s_, target=t, model='ridge', fset='only-' + g_), 'R2_oos', '{:+.3f}', label=f'E5 only {g_} {s_} {t}')} |")
        a(f"| | PSST + BDI + BAI together | - | - | {ci(E5M, dict(sample=s_, target=t, model='ridge', fset='only-questionnaires'), 'R2_oos', '{:+.3f}', label=f'E5 only questionnaires {s_} {t}')} |")
    a("")
table("T-E5-ablation", "ablation (ridge)", f"{E5M}, {E5D}, results/phase4_metrics.csv", "src/ext_E5_ablation_lc.py; src/phase4_report.py")
dd = df(E5D); dd = dd[dd.metric == "RMSE"]
cnt = lambda pre, cond: agg(E5D, f"metric == 'RMSE' and `first`.str.startswith('{pre}') and {cond}", None, "count", "{:.0f}", label=f"E5 ablation comparisons {pre} {cond}")
nr, nf = cnt("ridge", "delta == delta"), cnt("rf", "delta == delta")
qh = "`first` == 'ridge/D-hormones'"
a(f"**Ablation findings.** (1) *Dropping the hormones never costs anything.* In the ridge ablation (3 samples x 3 targets) dropping hormones left RMSE unchanged within the interval in all but {agg(E5D, qh + ' and metric == \"RMSE\" and excludes_0', None, 'count', '{:.0f}', label='E5 hormone drops with CI excluding 0')} cases, and in those the model was *better* without them (change in RMSE negative); for DRSP psychological, pooled, R2 was {ci(E5M, dict(sample='pooled', target='drsp_psych', model='ridge', fset='D-hormones'), 'R2_oos', '{:+.3f}', label='E5 drop hormones pooled drsp')} without hormones versus {ci('results/phase4_metrics.csv', dict(sample='pooled', target='drsp_psych', model='ridge', fset='D'), 'R2_oos', '{:+.3f}', label='E5 full D pooled drsp')} with them. Hormones alone: {ci(E5M, dict(sample='pooled', target='drsp_psych', model='ridge', fset='only-hormones'), 'R2_oos', '{:+.3f}', label='E5 only hormones pooled drsp')}. (2) *Phase matters for DRSP*: dropping phase raises RMSE by {ci(E5D, dict(sample='pooled', target='drsp_psych', first='ridge/D-phase', second='ridge/D', metric='RMSE'), 'delta', '{:+.3f}', lo='lo', hi='hi', label='E5 dRMSE drop phase pooled drsp')} (pooled, interval excludes 0); for positive affect and anxiety the change is at most {calc('E5 max |dRMSE| drop phase, affect/anxiety', float(dd[(dd['first'] == 'ridge/D-phase') & dd.target.isin(['pos_affect', 'stai']) & dd['sample'].isin(['pooled', 'long'])].delta.abs().max()), '{:.3f}', E5D, 'max |delta|, first == ridge/D-phase, targets pos_affect and stai, pooled and long')} RMSE units (the scales of these targets are about 1). (3) *BDI is the most valuable single group*: dropping it lowers pooled DRSP R2 to {ci(E5M, dict(sample='pooled', target='drsp_psych', model='ridge', fset='D-BDI'), 'R2_oos', '{:+.3f}', label='E5 drop BDI pooled drsp')}; BDI alone gives {ci(E5M, dict(sample='pooled', target='drsp_psych', model='ridge', fset='only-BDI'), 'R2_oos', '{:+.3f}', label='E5 only BDI pooled drsp')}, and the three questionnaires together {ci(E5M, dict(sample='pooled', target='drsp_psych', model='ridge', fset='only-questionnaires'), 'R2_oos', '{:+.3f}', label='E5 only questionnaires pooled drsp')}, essentially the whole of set D. PSST and BAI are partly interchangeable with BDI (BAI dropped: {ci(E5M, dict(sample='pooled', target='drsp_psych', model='ridge', fset='D-BAI'), 'R2_oos', '{:+.3f}', label='E5 drop BAI pooled drsp')}), the 'shared credit' effect described in the note. Many drop-one intervals include 0 because the targets are noisy and the groups overlap: the ablation shows the *order of magnitude* of each group's contribution, not exact values. (4) *Random forest* (drop-one, pooled and longitudinal, {nf} comparisons): {cnt('rf', 'delta < 0 and hi < 0')} significant improvements and {cnt('rf', 'delta > 0 and lo > 0')} significant deteriorations; ridge ({nr} comparisons): {cnt('ridge', 'delta < 0 and hi < 0')} and {cnt('ridge', 'delta > 0 and lo > 0')}. Figure: `results/fig_E5_ablation.png`.\n")
claim(int(agg(E5D, qh + ' and metric == "RMSE" and delta > 0 and lo > 0', None, "count", "{:.0f}")) == 0, "dropping hormones never significantly hurts")
claim(int(agg(E5D, qh + ' and metric == "RMSE" and excludes_0', None, "count", "{:.0f}")) == int(agg(E5D, qh + ' and metric == "RMSE" and delta < 0 and hi < 0', None, "count", "{:.0f}")), "hormone drops with CI excluding 0 are all improvements")
a("**Learning curves** (ridge; leave-one-woman-out with the training set restricted to k other women). Test = R2 versus the mean baseline trained on the same k women [95% CI over the held-out women]; train = mean R2 on the training women. Set D:\n")
for s_ in ["pooled", "long"]:
    ks = sorted(df(E5L)[df(E5L)["sample"] == s_].n_train_women.unique()); nrow_ = int(df(E5L)[df(E5L)["sample"] == s_].n_test_rows.iloc[0]); nwm = int(df(E5L)[df(E5L)["sample"] == s_].n_test_women.iloc[0])
    a(f"{SMP[s_].capitalize()} ({calc('LC test rows', nrow_, '{:.0f}', E5L, 'n_test_rows')} test rows, {calc('LC test women', nwm, '{:.0f}', E5L, 'n_test_women')} women), columns = number of training women:\n"); a("| Target | " + " | ".join(f"k = {kc(k)}" for k in ks) + " |\n|---|" + "---|" * len(ks))
    for t in TS: a(f"| {TN[t]} | " + " | ".join(f"{ci(E5L, dict(sample=s_, target=t, fset='D', n_train_women=float(k)), 'R2_oos', '{:+.2f}', label=f'E5 LC test {s_} {t} D k={int(k)}')} (train {val(E5L, dict(sample=s_, target=t, fset='D', n_train_women=float(k)), 'train_R2', '{:.2f}', label=f'E5 LC train {s_} {t} D k={int(k)}')})" for k in ks) + " |")
    a("")
table("T-E5-lc", "learning curves, set D", E5L, "src/ext_E5_ablation_lc.py")
